        setViewFilters((prev) => {
            const currentValues =
                Array.isArray(prev[key])
                    ? prev[key]
                    : [];

            const exists =
                currentValues.includes(value);

            return {
                ...prev,
                [key]: exists
                    ? currentValues.filter(
                        (item) =>
                            item !== value
                    )
                    : [
                        ...currentValues,
                        value,
                    ],
            };
        });
